+          stimer.tick();
+          tickCount.incrementAndGet();
+        } catch (InterruptedException e) {
+          throw new RuntimeException(e);
+        }
+      }
+    }).start();
+    long oldInterval = interval.get();
+    Thread.sleep(oldInterval / 2);
+    long tickCountInit = tickCount.get();
+    // scale in the interval
