+    stimer.update();
+    Thread.sleep(oldInterval);
+    long newTickCount = tickCount.get();
+    Assert.assertTrue("current tickCount = "
+        + newTickCount + " is not >= 5 + " + tickCountInit, newTickCount >= tickCountInit + 5);
+  }
